import heapq

def solve(n, roads):
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in roads:
        adj[u].append((v, w))
        adj[v].append((u, w))

    # Kruskal's algorithm using Union-Find
    parent = list(range(n))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        pu, pv = find(u), find(v)
        if pu == pv:
            return False
        parent[pu] = pv
        return True

    # Sort all edges by weight
    edges = []
    for u in range(n):
        for v, w in adj[u]:
            if u < v:  # To avoid duplicates
                edges.append((w, u, v))
    edges.sort()

    total_cost = 0
    roads_used = 0

    for w, u, v in edges:
        if union(u, v):
            total_cost += w
            roads_used += 1
            if roads_used == n - 1:
                break

    # Check if all cities are connected
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return -1

    return total_cost
